import React from "react";
import { motion } from "framer-motion";

export default function Inicio() {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.8 }}
      className="min-h-screen bg-gradient-to-br from-blue-50 to-green-100 p-8"
    >
      <div className="max-w-5xl mx-auto">
        <h1 className="text-4xl font-extrabold text-gray-900 mb-6 text-center">
          📖 Contexto del Proyecto
        </h1>
        <p className="text-lg text-gray-700 leading-relaxed text-justify">
          Este proyecto tiene como objetivo realizar un análisis exploratorio
          profundo sobre la base de datos de grupos de investigación reconocidos
          en Colombia. Se aplicaron técnicas de limpieza, normalización y
          visualización de datos para identificar patrones y relaciones clave
          dentro de los datos.  
          El ciclo de vida de Machine Learning se aplicó desde la recolección y
          preprocesamiento de los datos hasta el análisis de resultados y
          conclusiones finales.
        </p>
      </div>
    </motion.div>
  );
}
